    Bug 2011088 - Alternatively, use msgWindow of running URI when reporting POP3 error. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D279939

diff --git a/mailnews/local/src/Pop3Client.sys.mjs b/mailnews/local/src/Pop3Client.sys.mjs
index d03c7eeb633..ec291047419 100644
--- a/mailnews/local/src/Pop3Client.sys.mjs
+++ b/mailnews/local/src/Pop3Client.sys.mjs
@@ -1677,7 +1677,15 @@ export class Pop3Client {

     this._actionDone(Cr.NS_ERROR_FAILURE);

-    if (!this._msgWindow) {
+    let msgWindow = this._msgWindow;
+    if (!msgWindow) {
+      // If there's a message window on the URI, use that.
+      // (The getter for `msgWindow` may throw).
+      try {
+        msgWindow = this.runningUri?.msgWindow;
+      } catch {}
+    }
+    if (!msgWindow) {
       return;
     }

@@ -1699,7 +1707,7 @@ export class Pop3Client {
       "pop3ErrorDialogTitle",
       [this._server.prettyName]
     );
-    Services.prompt.alert(this._msgWindow.domWindow, errorTitle, errorMsg);
+    Services.prompt.alert(msgWindow.domWindow, errorTitle, errorMsg);
   }

